import { useState, useCallback, useEffect } from 'react';
import axios from 'axios';

// Custom hook untuk API fetching dengan cache
const useStockAPI = () => {
  const [cache, setCache] = useState({});
  const [cacheExpiry, setCacheExpiry] = useState({});
  
  const fetchStock = useCallback(async (params, forceRefresh = false) => {
    const { symbol } = params;
    
    // Create a cache key based on all params
    const cacheKey = JSON.stringify(params);
    
    // Get current time
    const now = new Date().getTime();
    
    // Check cache first if no force refresh
    if (!forceRefresh && cache[cacheKey] && cacheExpiry[cacheKey] && cacheExpiry[cacheKey] > now) {
      console.log(`Using cached data for ${symbol} with params:`, params);
      return cache[cacheKey];
    }
    
    // If not cached or expired, fetch from API
    try {
      const res = await axios.get("http://localhost:5000/stock", { params });
      
      if (res.data && res.data.data && Array.isArray(res.data.data)) {
        // Process data
        const sortedData = [...res.data.data].sort((a, b) => {
          const dateA = new Date(a.Date || a.Datetime);
          const dateB = new Date(b.Date || b.Datetime);
          return dateB - dateA; // Descending order
        });
        
        // Cache the data
        setCache(prevCache => ({
          ...prevCache,
          [cacheKey]: {
            data: sortedData,
            status: 'success',
            timestamp: now
          }
        }));
        
        setCacheExpiry(prevExpiry => ({
          ...prevExpiry,
          [cacheKey]: now + CACHE_DURATION
        }));
        
        return {
          data: sortedData,
          status: 'success',
          timestamp: now
        };
      } else {
        throw new Error('Invalid data format received from server');
      }
    } catch (err) {
      console.error('Error fetching stock data:', err);
      
      // Cache error for 1 minute to prevent constant retries on same error
      const errorResponse = {
        data: [],
        status: 'error',
        error: err.response?.data?.error || err.message || 'Unknown error',
        timestamp: now
      };
      
      setCache(prevCache => ({
        ...prevCache,
        [cacheKey]: errorResponse
      }));
      
      setCacheExpiry(prevExpiry => ({
        ...prevExpiry,
        [cacheKey]: now + 60000 // Cache errors for 1 minute
      }));
      
      return errorResponse;
    }
  }, [cache, cacheExpiry]);
  
  const preloadStockData = useCallback(async (symbols, interval = '1d', period = '5d') => {
    // Batch process to avoid overwhelming the API
    const batchSize = 5;
    const batches = [];
    
    // Split symbols into batches
    for (let i = 0; i < symbols.length; i += batchSize) {
      batches.push(symbols.slice(i, i + batchSize));
    }
    
    // Process each batch
    for (const batch of batches) {
      const promises = batch.map(symbol => {
        return fetchStock({
          symbol,
          interval,
          period
        });
      });
      
      await Promise.all(promises);
      
      // Small delay between batches
      if (batches.length > 1) {
        await new Promise(resolve => setTimeout(resolve, 300));
      }
    }
  }, [fetchStock]); // Ditambahkan CACHE_DURATION sebagai dependency
  
  // Clear expired cache entries
  useEffect(() => {
    const cleanupInterval = setInterval(() => {
      const now = new Date().getTime();
      let hasExpired = false;
      
      const newCacheExpiry = { ...cacheExpiry };
      
      // Check for expired items
      Object.entries(cacheExpiry).forEach(([key, expiry]) => {
        if (expiry < now) {
          delete newCacheExpiry[key];
          hasExpired = true;
        }
      });
      
      // Only update if something expired
      if (hasExpired) {
        setCacheExpiry(newCacheExpiry);
        
        // Also clean up the actual cache data
        const newCache = { ...cache };
        Object.keys(cache).forEach(key => {
          if (!newCacheExpiry[key]) {
            delete newCache[key];
          }
        });
        
        setCache(newCache);
      }
    }, 60000); // Check every minute
    
    return () => clearInterval(cleanupInterval);
  }, [cache, cacheExpiry]);
  
  return {
    fetchStock,
    preloadStockData,
    cache,
    clearCache: () => {
      setCache({});
      setCacheExpiry({});
    }
  };
};

export default useStockAPI;
